import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { setAccessToken, validateToken } from './services/api'; // Your Spotify API helper
import TrackSearch from './components/TrackSearch';
import { getTokenFromUrl } from './services/spotifyAuth'; // Ensure this is correct
import Modal from '@mui/material/Modal';
import Box from '@mui/material/Box';

const App = () => {
  const [authExpired, setAuthExpired] = useState(false); // Track authentication status

  // Check for Spotify access token in URL and set it
  useEffect(() => {
    const token = getTokenFromUrl();
    if (token) {
      setAccessToken(token.access_token);
      window.location.hash = ''; // Clear the URL hash
      setAuthExpired(false); // Reset auth expired state when token is set
    } else {
      // Validate token on load if available
      const checkAuth = async () => {
        const isValid = await validateToken();
        if (!isValid) {
          setAuthExpired(true); // Show re-login prompt if invalid
        }
      };
      checkAuth();
    }
  }, []);

  // Direct login function to initiate Spotify OAuth
  const handleLogin = () => {
    const clientId = 'YOUR_CLIENT_ID';
    const redirectUri = 'http://localhost:3000'; // Change if needed
    const authEndpoint = 'https://accounts.spotify.com/authorize';
    const scopes = [
      'user-read-private',
      'user-read-email',
      'playlist-read-private',
      'playlist-read-collaborative',
    ];

    // Construct the Spotify auth URL
    const authUrl = `${authEndpoint}?client_id=${clientId}&redirect_uri=${encodeURIComponent(
      redirectUri
    )}&scope=${scopes.join('%20')}&response_type=token&show_dialog=true`;

    // Redirect to Spotify login
    window.location.href = authUrl;
  };

  // Handle re-login
  const handleReLogin = () => {
    setAuthExpired(false);
    handleLogin();
  };

  return (
    <Router>
      <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
        <h1>Welcome to Track Similarity App</h1>
        <p>
          Use this app to search for tracks based on their rhythm and other parameters. You can
          listen to previews, analyze tracks, and build your perfect DJ set!
        </p>

        {/* Login Button */}
        <button onClick={handleLogin} style={{ marginBottom: '20px', padding: '10px' }}>
          Login with Spotify
        </button>

        {/* Route Definitions */}
        <Routes>
          <Route path="/" element={<TrackSearch onReLogin={handleReLogin} />} />
          {/* Other routes if necessary */}
          <Route path="*" element={<Navigate to="/" />} />
        </Routes>

        {/* Modal for Re-Login */}
        <Modal
          open={authExpired}
          onClose={() => setAuthExpired(false)}
          aria-labelledby="relogin-modal"
          aria-describedby="relogin-description"
        >
          <Box
            sx={{
              position: 'absolute',
              top: '50%',
              left: '50%',
              transform: 'translate(-50%, -50%)',
              width: 300,
              bgcolor: 'background.paper',
              border: '2px solid #000',
              boxShadow: 24,
              p: 4,
            }}
          >
            <h2 id="relogin-modal">Session Expired</h2>
            <p id="relogin-description">Please re-login to continue.</p>
            <button onClick={handleReLogin}>Re-Login</button>
          </Box>
        </Modal>
      </div>
    </Router>
  );
};

export default App;
